/**
 * Free-plan Living Studio Worker.
 *
 * Workers Static Assets serve the built SPA from `apps/studio/dist`. Requests under
 * `/api/*` are forwarded to the Python sidecar (`apps/studio-api`), which runs on
 * the developer's machine and is published by a free Cloudflare Quick Tunnel.
 * (Running the sidecar inside Cloudflare requires Workers Containers, which is
 * a paid-plan feature.)
 */

interface Env {
  ASSETS: Fetcher;
  /** Public origin of the sidecar, e.g. https://random.trycloudflare.com */
  SIDECAR_URL?: string;
}

const API_PREFIX = "/api/";

function sidecarError(detail: string): Response {
  return Response.json({ detail }, { status: 502 });
}

export default {
  async fetch(request: Request, env: Env): Promise<Response> {
    const url = new URL(request.url);

    if (!url.pathname.startsWith(API_PREFIX)) {
      return env.ASSETS.fetch(request);
    }

    const sidecar = env.SIDECAR_URL?.trim().replace(/\/+$/, "");
    if (!sidecar) {
      return sidecarError("SIDECAR_URL is not configured");
    }

    // The Quick Tunnel routes by hostname, so the Worker's Host must not leak.
    const headers = new Headers(request.headers);
    headers.delete("host");
    headers.delete("cf-connecting-ip");

    const target = new URL(`${url.pathname}${url.search}`, `${sidecar}/`);

    try {
      // Returning the upstream Response directly preserves SSE streaming for
      // `/api/chat`.
      return await fetch(
        new Request(target, {
          method: request.method,
          headers,
          body: request.body,
          redirect: "manual",
        }),
      );
    } catch (error) {
      return sidecarError(`Sidecar unreachable: ${(error as Error).message}`);
    }
  },
} satisfies ExportedHandler<Env>;
===APP===
"""FastAPI app for the Living Studio sidecar."""

from __future__ import annotations

import os
from pathlib import Path

from agentic_odi_core import ODIService
from agentic_odi_core.repository import Repository
from agentic_odi_core.sqlite_repository import SQLiteRepository
from fastapi import FastAPI
from fastapi.middleware.cors import CORSMiddleware
from fastapi.responses import FileResponse, JSONResponse
from fastapi.staticfiles import StaticFiles

from agentic_odi_studio_api.studio.router import router as studio_router

CORS_ORIGINS = [
    "tauri://localhost",
    "http://tauri.localhost",
    "http://localhost:5173",
    "http://127.0.0.1:5173",
    "http://localhost:8100",
    "http://127.0.0.1:8100",
]

DEFAULT_BACKEND = "local"


def default_spa_dist() -> Path:
    """Resolve the built SPA, preferring an explicit override."""
    configured = os.environ.get("AGENTIC_ODI_STUDIO_DIST")
    if configured:
        return Path(configured)
    return Path(__file__).resolve().parents[4] / "apps" / "studio" / "dist"


SPA_DIST = default_spa_dist()


def create_app(repo: Repository | None = None, backend: str | None = None) -> FastAPI:
    if repo is None:
        repo = SQLiteRepository()
    service = ODIService(repo)
    app = FastAPI(title="Agentic ODI Studio API")
    app.state.service = service
    app.state.backend = backend or os.environ.get("AGENTIC_ODI_BACKEND") or DEFAULT_BACKEND

    app.add_middleware(
        CORSMiddleware,
        allow_origins=CORS_ORIGINS,
        allow_credentials=False,
        allow_methods=["*"],
        allow_headers=["*"],
    )

    @app.get("/health")
    def health() -> dict:
        return {"status": "ok"}

    @app.get("/capabilities")
    def capabilities() -> dict:
        return {"capabilities": app.state.backend}

    app.include_router(studio_router)

    if SPA_DIST.is_dir() and not os.getenv("AGENTIC_ODI_DISABLE_SPA"):
        assets_dir = SPA_DIST / "assets"
        if assets_dir.is_dir():
            app.mount("/assets", StaticFiles(directory=assets_dir), name="assets")

        @app.get("/{full_path:path}", response_model=None)
        def spa_fallback(full_path: str) -> FileResponse | JSONResponse:
            candidate = (SPA_DIST / full_path).resolve()
            if full_path and candidate.is_file() and candidate.is_relative_to(SPA_DIST.resolve()):
                return FileResponse(candidate)
            index = SPA_DIST / "index.html"
            if index.is_file():
                return FileResponse(index)
            return JSONResponse({"detail": "Not Found"}, status_code=404)

    return app

