}

.chat-turn {
  display: flex;
  flex-direction: column;
  gap: 10px;
  min-width: 0;
}

.chat-turn--assistant {
  align-self: stretch;
}

.chat-turn--user {
  align-self: flex-end;
  max-width: 86%;
  align-items: flex-end;
}

.chat-turn--user .chat-turn__text {
  background: rgba(99, 102, 241, 0.16);
